// Experience describes activity; profiles change presentation, never physics.
export const PROFILES={
 walking:[{id:'eyes',label:'First person',distance:0,height:0,fov:-3},{id:'shoulder',label:'Over shoulder',distance:3,height:.4,side:.65,fov:-3},{id:'third',label:'Third person',distance:6,height:1.4,fov:0}],
 bike:[{id:'helmet',label:'Helmet',distance:0,height:0,fov:0},{id:'bars',label:'Handlebar',distance:0,height:-.4,front:.55,fov:4},{id:'chase',label:'Close chase',distance:5,height:1.6,fov:0},{id:'wide',label:'Wide chase',distance:9,height:3,fov:4}],
 drone:[{id:'fpv',label:'FPV nose',distance:0,height:0,fov:12},{id:'recon',label:'Stabilized recon',distance:0,height:0,fov:-12},{id:'chase',label:'Drone chase',distance:4,height:1.5,fov:3},{id:'overhead',label:'Inspection overhead',distance:1,height:9,fov:-5}],
 inspection:[{id:'close',label:'Close inspection',distance:0,height:0,fov:-12},{id:'context',label:'Context view',distance:3,height:1,fov:-3}],
 power:[{id:'meter',label:'Meter view',distance:0,height:0,fov:-8},{id:'context',label:'Connection overview',distance:3,height:1.8,fov:0}],
 camp:[{id:'eyes',label:'Camp first person',distance:0,height:0,fov:-4},{id:'context',label:'Camp overview',distance:5,height:2,fov:0}]
};
export function createExperience(){return {version:1,preferred:Object.fromEntries(Object.entries(PROFILES).map(([state,list])=>[state,list[0].id]))};}
export function migrateExperience(raw){if(raw===undefined)return createExperience();if(!raw||raw.version!==1||!raw.preferred||Array.isArray(raw.preferred)||typeof raw.preferred!=='object')throw Error('Invalid experience preferences');const out=createExperience();for(const [state,id]of Object.entries(raw.preferred)){if(!Object.hasOwn(PROFILES,state)||!PROFILES[state].some(p=>p.id===id))throw Error('Invalid POV profile');out.preferred[state]=id;}return out;}
export function experienceState(s,screen=''){if(['supplies','inventory'].includes(screen))return 'inspection';if(screen==='rig'||s.harvesting)return 'power';if(['resident','npc','cal'].includes(screen))return 'camp';return s.mode==='drone'?'drone':s.mode==='bike'?'bike':'walking';}
export function cyclePOV(preferences,state){const list=PROFILES[state],index=list.findIndex(p=>p.id===preferences.preferred[state]);preferences.preferred[state]=list[(index+1)%list.length].id;return preferences.preferred[state];}
export function selectedProfile(preferences,state){return PROFILES[state].find(p=>p.id===preferences.preferred[state])||PROFILES[state][0];}
// Segment-vs-AABB clipping: camera stops before walls instead of looking through them.
export function clipCamera(anchor,wanted,solids){let fraction=1;const delta=wanted.map((v,i)=>v-anchor[i]);for(const b of solids){const lo=[b.x-b.w,(b.minY??-100)-.18,b.z-b.d],hi=[b.x+b.w,(b.maxY??100)+.18,b.z+b.d];let enter=0,leave=1,hit=true;for(let i=0;i<3;i++){if(Math.abs(delta[i])<1e-8){if(anchor[i]<lo[i]||anchor[i]>hi[i]){hit=false;break;}}else{let a=(lo[i]-anchor[i])/delta[i],z=(hi[i]-anchor[i])/delta[i];if(a>z)[a,z]=[z,a];enter=Math.max(enter,a);leave=Math.min(leave,z);if(enter>leave){hit=false;break;}}}if(hit&&leave>=0&&enter<=1)fraction=Math.min(fraction,Math.max(0,enter-.04));}return anchor.map((v,i)=>v+delta[i]*fraction);}
export function cameraPose(s,profile,{distance=1,height=1}={}){const [x,y,z]=s.pos.toArray?s.pos.toArray():s.pos,yaw=s.yaw,back=profile.distance*distance,side=profile.side||0,front=profile.front||0;return [x+Math.sin(yaw)*(back-front)+Math.cos(yaw)*side,y+profile.height*height,z+Math.cos(yaw)*(back-front)-Math.sin(yaw)*side];}
